import pandas as pd

import config


def read_raw(name):
    """Read data/raw/<name>.csv with every column as text and lower-case names."""
    path = config.RAW_DIR / f"{name}.csv"
    if not path.exists():
        raise FileNotFoundError(
            f"{path} is missing. Run:  python -m src.download_data {name}")
    df = pd.read_csv(path, dtype=str, low_memory=False)
    df.columns = [c.strip().lower() for c in df.columns]
    return df


def missing_facade_columns(df, keys=None):
    """Return {key: configured_name} for configured columns not in the file."""
    keys = keys or list(config.FACADE_COLS)
    return {k: config.FACADE_COLS[k] for k in keys
            if config.FACADE_COLS[k] not in df.columns}


def normalize_status(series):
    """Map the many spellings of a facade rating to SAFE / SWARMP / UNSAFE.

    Anything else (no report filed, blank, ...) is kept as upper-case text so
    the data check can show it; the table builder drops those rows.
    """
    s = series.fillna("").astype(str).str.strip().str.upper()
    out = s.copy()
    out[s.str.contains("UNSAFE") | s.eq("UN")] = "UNSAFE"
    out[s.str.contains("SWARMP") | s.str.contains("REPAIR AND MAINT") | s.eq("SW")] = "SWARMP"
    out[s.eq("SAFE") | s.eq("OK")] = "SAFE"
    return out


RATINGS = ["SAFE", "SWARMP", "UNSAFE"]


def is_initial_filing(series):
    s = series.fillna("").astype(str).str.lower()
    mask = pd.Series(False, index=series.index)
    for word in config.INITIAL_FILING_WORDS:
        mask |= s.str.contains(word, regex=False)
    return mask


def clean_id(series):
    """Turn '1012345.0', ' 1012345 ' or 1012345 into the text '1012345'."""
    s = series.astype(str).str.strip()
    s = s.str.replace(r"\.0+$", "", regex=True)
    return s.where(s.str.fullmatch(r"\d+", na=False), None)


def make_bbl(borough, block, lot):
    """Build the 10-digit borough-block-lot key that PLUTO uses."""
    boro = borough.fillna("").astype(str).str.strip().str.upper().map(config.BOROUGH_CODES)
    blk = clean_id(block)
    lt = clean_id(lot)
    bbl = boro + blk.str.zfill(5) + lt.str.zfill(4)
    return bbl.where(bbl.str.fullmatch(r"\d{10}", na=False), None)


def clean_pluto_bbl(series):
    """PLUTO's API returns bbl like '1000010010.00000000'."""
    s = series.astype(str).str.strip().str.replace(r"\.\d+$", "", regex=True)
    return s.where(s.str.fullmatch(r"\d{10}", na=False), None)


def parse_ecb_date(series):
    """ECB issue_date is stored as YYYYMMDD."""
    s = clean_id(series)
    return pd.to_datetime(s, format="%Y%m%d", errors="coerce")
